package dev.zomboid.hordes;
import com.google.gson.*;import java.util.*;import net.minecraft.server.level.ServerPlayer;import net.minecraft.resources.ResourceLocation;import net.minecraft.network.RegistryFriendlyByteBuf;import net.minecraft.network.codec.StreamCodec;import net.minecraft.network.protocol.common.custom.CustomPacketPayload;import net.neoforged.neoforge.network.PacketDistributor;
public final class AdminNetwork {
 public record View(String json) implements CustomPacketPayload{public static final Type<View> TYPE=new Type<>(ResourceLocation.fromNamespaceAndPath("zomboid_hordes","admin_view25"));public static final StreamCodec<RegistryFriendlyByteBuf,View> CODEC=StreamCodec.of((b,v)->b.writeUtf(v.json(),8192),b->new View(b.readUtf(8192)));public Type<View> type(){return TYPE;}}
 public record Apply(String json) implements CustomPacketPayload{public static final Type<Apply> TYPE=new Type<>(ResourceLocation.fromNamespaceAndPath("zomboid_hordes","admin_apply25"));public static final StreamCodec<RegistryFriendlyByteBuf,Apply> CODEC=StreamCodec.of((b,v)->b.writeUtf(v.json(),8192),b->new Apply(b.readUtf(8192)));public Type<Apply> type(){return TYPE;}}
 private static String json(boolean applied,String message){JsonObject j=new JsonObject();j.addProperty("revision",WorldTuning.revision());j.addProperty("applied",applied);j.addProperty("message",message);JsonObject rows=new JsonObject();WorldTuning.snapshot().forEach((k,v)->rows.addProperty(k,v));j.add("values",rows);j.addProperty("cleanup_message",ItemCleanup.message());return j.toString();}
 public static void open(ServerPlayer p){if(!p.createCommandSourceStack().hasPermission(2))return;WorldTuning.load(p.getServer());PacketDistributor.sendToPlayer(p,new View(json(false,"Edita los valores y pulsa Aplicar para guardar.")));}
 @net.neoforged.fml.common.EventBusSubscriber(modid="zomboid_hordes",bus=net.neoforged.fml.common.EventBusSubscriber.Bus.MOD)
 public static final class Registration{@net.neoforged.bus.api.SubscribeEvent public static void register(net.neoforged.neoforge.network.event.RegisterPayloadHandlersEvent e){AdminNetwork.register(e);}}
 public static void register(net.neoforged.neoforge.network.event.RegisterPayloadHandlersEvent e){var r=e.registrar("25");r.playToClient(View.TYPE,View.CODEC,(packet,context)->context.enqueueWork(()->{try{Class.forName("dev.zomboid.hordes.client.AdminScreen").getMethod("receive",String.class).invoke(null,packet.json());}catch(ReflectiveOperationException ex){System.err.println("[Zomboid Hordes] Admin screen failed: "+ex.getMessage());}}));r.playToServer(Apply.TYPE,Apply.CODEC,(packet,context)->context.enqueueWork(()->{
  if(!(context.player() instanceof ServerPlayer p))return;
  if(!p.createCommandSourceStack().hasPermission(2)){p.sendSystemMessage(net.minecraft.network.chat.Component.literal("Necesitas permisos de administrador para cambiar la dificultad."));return;}
  WorldTuning.load(p.getServer());boolean applied=false;String message;
  try{JsonObject j=JsonParser.parseString(packet.json()).getAsJsonObject();JsonObject edits=j.getAsJsonObject("values");Map<String,Double> values=new HashMap<>();for(var entry:edits.entrySet())values.put(entry.getKey(),entry.getValue().getAsDouble());ItemCleanup.stage(j.has("cleanup_message")?j.get("cleanup_message").getAsString():ItemCleanup.DEFAULT_MESSAGE);try{WorldTuning.batch(values,j.get("revision").getAsInt());}finally{ItemCleanup.unstage();}applied=true;message="Cambios aplicados y guardados en este mundo.";}catch(RuntimeException|java.io.IOException error){message="No se aplicó ningún cambio: "+error.getMessage();}
  PacketDistributor.sendToPlayer(p,new View(json(applied,message)));
 }));}
}
